export const CollectionStats = ({
  theme,
  items,
  featured,
  layout = "row",
  reverse = false,
  appearance = "simple",
  backgroundImage,
}: CollectionStatsProps) => {
  if (backgroundImage) {
    const variant = (() => {
      if (layout === "row") {
        return "default";
      }
      if (layout === "three-columns") {
        return "three-columns";
      }
      if (reverse) {
        return "bento-reversed";
      }
      return "bento";
    })();
    return (
      <__OverlayStats
        backgroundImageSrc={backgroundImage.src}
        theme={theme}
        variant={variant}
        {...(featured
          ? { featuredLabel: featured.label, featuredStat: featured.value }
          : {})}
        {...(items ? { stats: items } : {})}
      />
    );
  }
  if (layout === "row") {
    return (
      <__SimpleStats
        theme={theme}
        variant={(() => {
          if (appearance === "simple") {
            return "default";
          }
          if (appearance === "accent") {
            return "boxed";
          }
          return appearance;
        })()}
        {...(items ? { stats: items } : {})}
      />
    );
  }
  return (
    <__GridStats
      layout={layout === "bento" && reverse ? "bento-reversed" : layout}
      theme={theme}
      variant={appearance === "accent" ? "accent-column" : appearance}
      {...(featured
        ? { featuredLabel: featured.label, featuredStat: featured.value }
        : {})}
      {...(items ? { stats: items } : {})}
    />
  );
};

